"use strict";
(()=>{
const QUESTION_SETS={"place-value":[["What is the value of 6 in 6,245?",["6","60","600","6,000"],"6,000"],["Which digit is in the tens place in 3,482?",["3","4","8","2"],"8"],["500 + 20 + 7 = ?",["527","572","507","5,027"],"527"],["Which digit is in the hundreds place in 7,341?",["7","3","4","1"],"3"],["What is the value of 9 in 2,915?",["9","90","900","9,000"],"900"],["4 thousands + 2 hundreds + 3 tens + 1 one = ?",["4,231","4,321","4,203","4,123"],"4,231"],["Which digit is in the ones place in 5,806?",["5","8","0","6"],"6"],["70 is the same as how many tens?",["5","6","7","8"],"7"],["What is the value of 5 in 5,064?",["5","50","500","5,000"],"5,000"],["8,000 + 300 + 20 + 4 = ?",["8,234","8,324","8,304","8,034"],"8,324"]],"odd-even":[["Which number is even?",["7","9","12","15"],"12"],["Which number is odd?",["18","22","31","40"],"31"],["Is 46 odd or even?",["Odd","Even"],"Even"],["Which number is odd?",["10","24","37","52"],"37"],["Which number is even?",["13","25","36","49"],"36"],["Is 75 odd or even?",["Odd","Even"],"Odd"],["Which pair contains two even numbers?",["4 and 8","3 and 6","5 and 9","7 and 10"],"4 and 8"],["Which pair contains two odd numbers?",["2 and 5","7 and 11","4 and 8","6 and 9"],"7 and 11"],["What comes next in the even pattern 2, 4, 6, __?",["7","8","9","10"],"8"],["What comes next in the odd pattern 1, 3, 5, __?",["6","7","8","9"],"7"]],"fractions":[["Which means one half?",["1/2","1/3","2/3","1/4"],"1/2"],["Two equal parts make how many halves?",["1","2","3","4"],"2"],["Which is one of four equal parts?",["1/2","1/3","1/4","3/4"],"1/4"],["Which fraction means one whole split into three equal parts, with one part chosen?",["1/2","1/3","2/3","3/4"],"1/3"],["Two quarters are equal to?",["1/2","1/3","1/4","1 whole"],"1/2"],["Which is larger?",["1/2","1/4"],"1/2"],["Four quarters make?",["1/2","1 whole","2 wholes","1/4"],"1 whole"],["Which fraction shows three out of four equal parts?",["3/4","1/4","2/3","1/3"],"3/4"],["If a pizza is cut into 2 equal pieces, one piece is?",["1/2","1/3","1/4","2/3"],"1/2"],["If a shape has 4 equal parts and 1 is coloured, the coloured part is?",["1/2","1/3","1/4","3/4"],"1/4"]],"time-calendar":[["60 minutes equals?",["1 hour","2 hours","1 day","30 minutes"],"1 hour"],["How many days are in one week?",["5","6","7","8"],"7"],["Which month comes after March?",["January","February","April","June"],"April"],["How many months are in one year?",["10","11","12","13"],"12"],["30 minutes is?",["Half an hour","One hour","Two hours","One day"],"Half an hour"],["Which day comes after Friday?",["Thursday","Saturday","Sunday","Monday"],"Saturday"],["If school starts at 9:00 and one hour passes, what time is it?",["9:30","10:00","10:30","11:00"],"10:00"],["Which day comes before Wednesday?",["Monday","Tuesday","Thursday","Friday"],"Tuesday"],["Which season is commonly associated with the hottest weather?",["Spring","Summer","Autumn","Winter"],"Summer"],["Which month comes before December?",["October","November","January","September"],"November"]],"indian-money":[["₹10 + ₹5 = ?",["₹12","₹15","₹20","₹50"],"₹15"],["Two ₹20 notes make?",["₹20","₹30","₹40","₹50"],"₹40"],["₹50 − ₹20 = ?",["₹20","₹25","₹30","₹40"],"₹30"],["₹20 + ₹20 + ₹10 = ?",["₹40","₹50","₹60","₹70"],"₹50"],["Which amount is greater?",["₹25","₹50"],"₹50"],["₹100 − ₹40 = ?",["₹40","₹50","₹60","₹70"],"₹60"],["Five ₹10 notes make?",["₹30","₹40","₹50","₹60"],"₹50"],["₹5 + ₹5 + ₹5 = ?",["₹10","₹15","₹20","₹25"],"₹15"],["You have ₹50 and spend ₹15. How much is left?",["₹25","₹30","₹35","₹40"],"₹35"],["Which combination makes ₹30?",["₹20 + ₹10","₹10 + ₹5","₹50 + ₹10","₹20 + ₹20"],"₹20 + ₹10"]],"measurement":[["100 centimetres equals?",["1 metre","10 metres","1 kilometre","1 litre"],"1 metre"],["1,000 grams equals?",["1 kilogram","10 kilograms","100 grams","1 litre"],"1 kilogram"],["1,000 millilitres equals?",["1 litre","10 litres","100 ml","1 metre"],"1 litre"],["Which unit is best for the length of a pencil?",["Centimetres","Kilometres","Litres","Kilograms"],"Centimetres"],["Which unit is best for the weight of a bag of rice?",["Kilograms","Litres","Metres","Minutes"],"Kilograms"],["Which unit is best for water in a bottle?",["Litres","Kilometres","Kilograms","Hours"],"Litres"],["Which is longer?",["1 metre","50 centimetres"],"1 metre"],["500 grams is half of?",["1 kilogram","2 kilograms","100 grams","5 kilograms"],"1 kilogram"],["500 millilitres + 500 millilitres = ?",["1 litre","2 litres","100 ml","50 litres"],"1 litre"],["1 kilometre equals how many metres?",["100","500","1,000","10,000"],"1,000"]]};
const params=new URLSearchParams(location.search),topic=params.get('topic');if(!QUESTION_SETS[topic])return;document.body.dataset.activity='math-extra-quiz';
const root=document.getElementById('practiceRoot'),head=document.querySelector('.practice-head h1'),feedback=document.getElementById('practiceFeedback');
const labels={'place-value':'Place Value','odd-even':'Odd & Even','fractions':'Fractions','time-calendar':'Time & Calendar','indian-money':'Indian Money','measurement':'Measurement'};
const lesson={'place-value':'place-value.html','odd-even':'odd-even.html','fractions':'fractions.html','time-calendar':'time-calendar.html','indian-money':'indian-money.html','measurement':'measurement.html'};
const next={'place-value':['odd-even.html','Odd & Even'],'odd-even':['fractions.html','Fractions'],'fractions':['time-calendar.html','Time & Calendar'],'time-calendar':['indian-money.html','Indian Money'],'indian-money':['measurement.html','Measurement'],'measurement':['quiz-hub.html','More quizzes']};
if(head)head.textContent=labels[topic]+' Quiz';
const speak=text=>{if(!('speechSynthesis'in window))return;const synth=window.speechSynthesis;synth.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-IN';u.rate=.78;const voices=synth.getVoices?.()||[];u.voice=voices.find(v=>String(v.lang).toLowerCase()==='en-in')||voices.find(v=>String(v.lang).toLowerCase().startsWith('en'))||null;synth.speak(u)};
const shuffle=list=>[...list].sort(()=>Math.random()-.5);const items=QUESTION_SETS[topic];let index=0,score=0;
function finish(){const n=next[topic];root.innerHTML='<section class="practice-box"><p class="game-progress">Quiz complete</p><p class="game-question">'+score+' / '+items.length+'</p><p class="game-feedback">'+(score===items.length?'Excellent work!':'Good work! Review the lesson and try again.')+'</p><div id="sharedScoreCard"></div><div class="journey-actions"><button id="playAgain" class="practice-button journey-primary" type="button">Play again</button><a class="practice-button journey-secondary" href="'+lesson[topic]+'">Review '+labels[topic]+' lesson</a><a class="practice-button journey-secondary" href="'+n[0]+'">Next: '+n[1]+' →</a></div></section>';window.renderLearnWithUsScoreCard?.({container:document.getElementById('sharedScoreCard'),score,total:items.length,title:labels[topic]+' quiz complete!',subtitle:'Keep learning and share your achievement.',filename:'learnwithus-'+topic+'-score.svg',url:'math-quiz.html?topic='+topic});window.LearnWithUs?.recordQuiz?.(labels[topic]+' quiz',score,items.length,'math-quiz.html?topic='+topic);document.getElementById('playAgain').onclick=()=>location.reload()}
function round(){if(index===items.length)return finish();const q=items[index];root.innerHTML='<section class="practice-box"><p class="game-progress">Question '+(index+1)+' of '+items.length+'</p><p class="game-question">'+q[0]+'</p><div class="game-options" id="extraQuizOptions"></div><p class="game-feedback" id="extraQuizFeedback" role="status" aria-live="polite"></p><button class="practice-button game-next" id="extraQuizNext" type="button" hidden>'+(index===items.length-1?'See score →':'Next →')+'</button></section>';const row=document.getElementById('extraQuizOptions'),status=document.getElementById('extraQuizFeedback'),nextBtn=document.getElementById('extraQuizNext');shuffle(q[1]).forEach(value=>{const b=document.createElement('button');b.type='button';b.textContent=value;b.onclick=()=>{const ok=String(value)===String(q[2]);row.querySelectorAll('button').forEach(x=>{x.disabled=true;if(x.textContent===String(q[2]))x.classList.add('correct')});b.classList.add(ok?'correct':'wrong');const msg=ok?'Correct answer!':'Wrong answer. The correct answer is '+q[2]+'.';status.textContent=msg;speak(msg);if(ok)score++;nextBtn.hidden=false;nextBtn.focus();nextBtn.onclick=()=>{index++;round()}};row.append(b)})}round();})();
